      pt: "Este é um dos parques nacionais mais antigos de Itália. Protege o habitat do urso-pardo dos Apeninos.",
      fr: "C'est l'un des plus anciens parcs nationaux d'Italie. Il protège l'habitat de l'ours brun de l'Apennin.",
