      ro: ["Înființat în 1975 ca primul parc regional din regiunea Toscana.", "Acoperă o suprafață totală de aproximativ 9.800 de hectare.", "Include dealurile Uccellina, cu o înălțime maximă de 417 metri.", "Linia de coastă protejată are o lungime de circa 25 kilometri.", "Adăpostește ruinele abației San Rabano, datând din secolul al XI-lea.", "Este locul de origine al vitelor Maremmana și al păstorilor butteri."],
      en: ["Founded in 1975 as the first regional park in Tuscany.", "Covers a total area of approximately 9,800 hectares.", "Includes the Uccellina hills, reaching up to 417 meters in height.", "The protected coastline spans about 25 kilometers.", "Protects the ruins of the 11th-century Abbey of San Rabano.", "Home to the unique Maremmana cattle and traditional butteri cowboys."],
      es: ["Fundado en el año 1975 como el primer parque regional de la Toscana.", "Se extiende sobre una superficie de unas 9.800 hectáreas.", "Incluye los Monti dell'Uccellina con hasta 417 metros de altura.", "La línea costera del parque tiene unos 25 kilómetros de largo.", "Protege las ruinas de la abadía de San Rabano del siglo XI.", "Hogar de las vacas Maremmana y de los tradicionales butteri."],
      pt: ["Fundado no ano de 1975 como o primeiro parque regional da Toscana.", "Estende-se por uma área de cerca de 9.800 hectares.", "Inclui os Monti dell'Uccellina com até 417 metros de altitude.", "A linha costeira do parque tem cerca de 25 quilómetros de extensão.", "Protege as ruínas da abadia de San Rabano do século XI.", "Lar do gado Maremmana e dos tradicionais butteri."],
