    imageHint: "Botanical Garden of Naples greenhouses",
    descriptionAdvanced: {
      de: "Der Botanische Garten von Neapel, auch bekannt als Real Orto Botanico, wurde im Jahr 1807 durch ein Dekret von Joseph Bonaparte gegründet und 1810 unter Joachim Murat fertiggestellt. Er erstreckt sich über eine Fläche von etwa 12 Hektar im Stadtteil San Carlo all'Arena und wird von der Universität Neapel Federico II verwaltet. Der Garten beherbergt heute rund 25.000 Pflanzenexemplare, die etwa 10.000 verschiedenen Arten angehören. Die Anlage ist in verschiedene Sektoren unterteilt, darunter das Arboretum, die Sukkulenten-Sammlung, das Farnhaus und der experimentelle Bereich für Nutzpflanzen. Besonders bemerkenswert ist das historische Gewächshaus, das im 19. Jahrhundert errichtet wurde und heute als Monument der Architekturgeschichte gilt. Der Garten dient nicht nur der Erhaltung seltener Pflanzenarten, sondern ist auch ein wichtiges Zentrum für botanische Forschung und Umweltbildung in Süditalien. Durch seine zentrale Lage bietet er eine grüne Oase inmitten der dicht besiedelten Metropole Neapel und bewahrt gleichzeitig das wissenschaftliche Erbe der Bourbonen-Zeit.",
      hu: "A Nápolyi Botanikus Kert, hivatalos nevén Real Orto Botanico, 1807-ben jött létre Joseph Bonaparte rendelete alapján, majd 1810-ben Joachim Murat idején készült el véglegesen. A kert mintegy 12 hektáron terül el a város San Carlo all'Arena negyedében, és a nápolyi II. Frigyes Egyetem kezelésében áll. Jelenleg körülbelül 25 000 növényi példánynak ad otthont, amelyek közel 10 000 különböző fajt képviselnek a világ minden tájáról. A gyűjtemény tematikus szektorokra oszlik, mint például az arborétum, a pozsgás növények részlege, a páfrányház és a haszonnövények kísérleti területe. Kiemelkedő látványossága a 19. században épült történelmi üvegház, amely ma már építészeti műemléknek számít. A kert nemcsupán a ritka fajok megőrzését szolgálja, hanem Dél-Olaszország egyik legfontosabb botanikai kutatóközpontja és oktatási helyszíne is. Központi elhelyezkedése révén zöld oázist biztosít Nápoly sűrűn lakott belvárosában, miközben őrzi a Bourbon-korszak tudományos örökségét.",
      ro: "Grădina Botanică din Napoli, cunoscută oficial sub numele de Real Orto Botanico, a fost fondată în anul 1807 printr-un decret al lui Joseph Bonaparte și finalizată în 1810 sub conducerea lui Joachim Murat. Aceasta se întinde pe o suprafață de aproximativ 12 hectare în cartierul San Carlo all'Arena și este administrată de Universitatea din Napoli Federico II. Grădina găzduiește în prezent circa 25.000 de specimene vegetale, aparținând unui număr de aproximativ 10.000 de specii diferite din întreaga lume. Amenajarea este împărțită în mai multe sectoare tematice, inclusiv arboretumul, colecția de plante suculente, ferăria și zona experimentală pentru plante utilitare. Un element remarcabil este sera istorică construită în secolul al XIX-lea, care reprezintă un monument important al arhitecturii de fier și sticlă. Pe lângă rolul său în conservarea speciilor rare, grădina este un centru esențial pentru cercetarea botanică și educația ecologică în sudul Italiei. Situată central, aceasta oferă o oază de liniște și verdeață în mijlocul metropolei napoletane, păstrând moștenirea științifică a epocii bourbonice.",
      en: "The Botanical Garden of Naples, officially known as the Real Orto Botanico, was founded in 1807 by a decree of Joseph Bonaparte and completed in 1810 under Joachim Murat. Spanning approximately 12 hectares in the San Carlo all'Arena district, it is managed by the University of Naples Federico II. The garden currently houses about 25,000 plant specimens, representing nearly 10.000 different species from all over the world. The facility is divided into various thematic sectors, including the arboretum, the succulent collection, the fern house, and the experimental area for economic plants. A particularly notable feature is the historical greenhouse built in the 19th century, which is now considered a monument of architectural and scientific history. The garden serves not only as a sanctuary for rare plant species but also as a major center for botanical research and environmental education in Southern Italy. Its central location provides a vital green space within the densely populated city of Naples while preserving the scientific heritage of the Bourbon era.",
      es: "El Jardín Botánico de Nápoles, también conocido como Real Orto Botanico, fue fundado en 1807 por un decreto de José Bonaparte y terminado en 1810 bajo Joaquín Murat. Se extiende sobre una superficie de aproximadamente 12 hectáreas en el distrito de San Carlo all'Arena y es gestionado por la Universidad de Nápoles Federico II. El jardín alberga hoy alrededor de 25.000 ejemplares de plantas pertenecientes a unas 10.000 especies diferentes. El recinto está dividido en varios sectores, incluyendo el arboreto, la colección de suculentas, el helechal y el área experimental para plantas útiles. Es particularmente notable el invernadero histórico, construido en el siglo XIX y considerado hoy un monumento de la historia de la arquitectura. El jardín no solo sirve para la conservación de especies vegetales raras, sino que también es un importante centro de investigación botánica y educación ambiental en el sur de Italia. Gracias a su ubicación central, ofrece un oasis verde en medio de la densamente poblada metrópoli de Nápoles, preservando al mismo tiempo el legado científico de la época borbónica.",
      pt: "O Jardim Botânico de Nápoles, também conhecido como Real Orto Botanico, foi fundado em 1807 por um decreto de José Bonaparte e concluído em 1810 sob Joaquim Murat. Estende-se por uma área de cerca de 12 hectares no bairro de San Carlo all'Arena e é gerido pela Universidade de Nápoles Federico II. O jardim alberga hoje cerca de 25.000 exemplares de plantas, pertencentes a aproximadamente 10.000 espécies diferentes. O complexo está dividido em vários setores, incluindo o arboreto, a coleção de suculentas, o fetário e a área experimental para plantas úteis. É particularmente notável a estufa histórica, construída no século XIX e considerada hoje um monumento da história da arquitetura. O jardim não serve apenas para a conservação de espécies vegetais raras, mas é também um importante centro de investigação botânica e educação ambiental no sul de Itália. Graças à sua localização central, oferece um oásis verde no meio da densamente povoada metrópole de Nápoles, preservando ao mesmo tempo a herança científica do período bourbónico.",
      fr: "Le Jardin botanique de Naples, également connu sous le nom de Real Orto Botanico, a été fondé en 1807 par un décret de Joseph Bonaparte et achevé en 1810 sous Joachim Murat. Il s'étend sur une superficie d'environ 12 hectares dans le quartier de San Carlo all'Arena et est géré par l'Université de Naples - Frédéric-II. Le jardin abrite aujourd'hui environ 25 000 spécimens de plantes appartenant à quelque 10 000 espèces différentes. L'ensemble est divisé en plusieurs secteurs, dont l'arboretum, la collection de succulentes, la fougeraie et la zone expérimentale pour les plantes utiles. La serre historique, érigée au XIXe siècle et aujourd'hui considérée comme un monument de l'histoire de l'architecture, est particulièrement remarquable. Le jardin ne sert pas seulement à la conservation d'espèces végétales rares, mais constitue également un centre important pour la recherche botanique et l'éducation environnementale dans le sud de l'Italie. Grâce à sa position centrale, il offre une oasis de verdure au cœur de la métropole de Naples, tout en préservant l'héritage scientifique de l'époque bourbonienne.",
    },
