      hu: ["1977-ben alapították állami természetvédelmi területként.", "A rezervátum területe körülbelül 465 hektár.", "1977 óta az UNESCO Bioszféra-rezervátum része.", "Átlagosan 1200 méteres magasságban fekszik.", "Ritka jégkorszak utáni jegenyefenyő-állományt véd.", "Kiemelt erdészeti kutatási terület Közép-Olaszországban."],
      ro: ["Înființată în anul 1977 ca rezervație naturală de stat.", "Acoperă o suprafață de aproximativ 465 de hectare.", "Integrată în programul UNESCO Man and Biosphere din 1977.", "Situată la o altitudine medie de 1.200 de metri.", "Protejează păduri rare de brad alb de origine post-glaciară.", "Este un sit de referință pentru cercetările silvice."],
      en: ["Established in 1977 as a state nature reserve.", "Covers a total area of approximately 465 hectares.", "Part of the UNESCO Biosphere Reserve since 1977.", "Located at an average elevation of 1,200 meters.", "Protects rare post-glacial stands of silver fir.", "A key site for forestry research and ecological studies."],
      es: ["Fundada en el año 1977 como reserva natural estatal.", "Abarca una superficie de unas 465 hectáreas.", "Parte de la Reserva de la Biosfera de la UNESCO desde 1977.", "Situada a una altitud de unos 1.200 metros.", "Protege poblaciones raras de abeto blanco post-glaciales.", "Importante área de investigación para la silvicultura."],
      pt: ["Fundada no ano de 1977 como reserva natural estatal.", "Abrange uma área de cerca de 465 hectares.", "Parte da Reserva da Biosfera da UNESCO desde 1977.", "Situada a uma altitude de cerca de 1.200 metros.", "Protege povoamentos raros de abeto-branco pós-glaciares.", "Área de investigação importante para a silvicultura."],
      fr: ["Fondée en 1977 en tant que réserve naturelle d'État.", "Couvre une superficie d'environ 465 hectares.", "Fait partie de la réserve de biosphère de l'UNESCO depuis 1977.", "Située à une altitude d'environ 1 200 mètres.", "Protège de rares peuplements de sapins blancs post-glaciaires.", "Zone de recherche importante pour la sylviculture."],
